# WX Huddle · Halloween Edition
# Run: streamlit run WX_Huddle_Halloween.py
# Public deployment: add this file and requirements.txt to a GitHub repository.
# In Streamlit Community Cloud, select Create app, that repository, and this file.
# Choose public app sharing so participants need no account.
# Room data is shared across participants in one running app instance.
# Community Cloud local files are ephemeral: app redeploys/reboots can reset rooms.
# The Python V8 wheel and Streamlit/browser flow were not executable in the local
# build environment; the Python service was tested against the same JS engine in Node.
"""Shared, transaction-safe game service for the single Streamlit app instance."""
import hashlib
import json
import re
import secrets
import sqlite3
import threading
import time
from collections import defaultdict, deque
from contextlib import closing
from pathlib import Path


class GameService:
    def __init__(self, engine_source, database_path, runtime=None):
        if runtime is None:
            from py_mini_racer import MiniRacer
            runtime = MiniRacer()
        self.runtime = runtime
        self.runtime.eval(engine_source)
        self.database_path = str(database_path)
        self.lock = threading.RLock()
        self.rates = defaultdict(deque)
        Path(self.database_path).parent.mkdir(parents=True, exist_ok=True)
        with closing(sqlite3.connect(self.database_path)) as db, db:
            db.execute('PRAGMA journal_mode=WAL')
            db.execute('CREATE TABLE IF NOT EXISTS wx_rooms (code TEXT PRIMARY KEY, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, expires_at INTEGER NOT NULL)')

    @staticmethod
    def _secret(value):
        if not isinstance(value, str) or not re.fullmatch(r'[a-zA-Z0-9_-]{32,128}', value):
            raise ValueError('Your private session key is invalid. Refresh and try again.')
        return hashlib.sha256(value.encode()).hexdigest()

    def handle(self, message, client_id):
        try:
            if not isinstance(message, dict):
                raise ValueError('Send a valid game action.')
            body = message.get('body')
            if not isinstance(body, dict) or len(json.dumps(body)) > 16384:
                raise ValueError('That game action is too long or could not be read.')
            body = dict(body)
            op = body.get('op', 'state')
            token = message.get('token', '')
            token_hash = self._secret(token) if token else None
            if op in ('create', 'join', 'recover'):
                body['sessionHash'] = self._secret(body.pop('session', None))
                body['recoveryHash'] = self._secret(body.pop('recovery', None))
                if op == 'recover':
                    body['oldRecoveryHash'] = self._secret(body.pop('key', None))
            # Browser-supplied fields cannot replace server-calculated hashes.
            elif any(k in body for k in ('sessionHash', 'recoveryHash', 'oldRecoveryHash')):
                raise ValueError('That game action is invalid.')
            if op == 'create':
                alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
                h = body['sessionHash']
                code = ''.join(alphabet[int(h[i*2:i*2+2], 16) & 31] for i in range(8))
                body['demo'] = False
            else:
                code = str(body.get('room', '')).upper().replace(' ', '')
                if not re.fullmatch(r'[A-HJ-NP-Z2-9]{8}', code):
                    raise ValueError('Enter the eight-character huddle code.')
            now = int(time.time() * 1000)
            with self.lock:
                key = token_hash or client_id
                rate = self.rates[key]
                while rate and now-rate[0] > 60000:
                    rate.popleft()
                if len(rate) >= 300:
                    return {'status': 429, 'data': {'error': 'Please wait a moment before trying again.'}}
                rate.append(now)
                if len(self.rates) > 5000:
                    self.rates = defaultdict(deque, {k:v for k,v in self.rates.items() if v and now-v[-1] < 60000})
                with closing(sqlite3.connect(self.database_path, timeout=10)) as db, db:
                    db.execute('BEGIN IMMEDIATE')
                    row = db.execute('SELECT state, version FROM wx_rooms WHERE code=?', (code,)).fetchone()
                    payload = dict(body=body, code=code, room=json.loads(row[0]) if row else None,
                                   version=row[1] if row else 0, tokenHash=token_hash, now=now,
                                   entropy=secrets.token_hex(4096))
                    result = self.runtime.call('WXServer.run', payload)
                    if result['status'] >= 400:
                        db.rollback()
                    elif result.get('changed'):
                        room = result['room']
                        version = room['revision']
                        db.execute('INSERT INTO wx_rooms (code,state,version,expires_at) VALUES (?,?,?,?) ON CONFLICT(code) DO UPDATE SET state=excluded.state,version=excluded.version,expires_at=excluded.expires_at',
                                   (code, json.dumps(room, ensure_ascii=False), version, room['expiresAt']))
                        if op == 'create':
                            db.execute('DELETE FROM wx_rooms WHERE expires_at < ?', (now,))
                    # Return only the permission-filtered projection to the iframe.
                    return {'status': result['status'], 'data': result['data']}
        except ValueError as exc:
            return {'status': 400, 'data': {'error': str(exc)}}
        except Exception:
            return {'status': 500, 'data': {'error': 'The connection was interrupted. Please try again.'}}

ENGINE_B64 = ""
HTML_B64 = ""
import base64
import gzip
import os
import tempfile
import urllib.parse
import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title='WX Huddle · Halloween Edition', page_icon='🎃', layout='wide', initial_sidebar_state='collapsed')
st.markdown('''<style>
html,body,[data-testid="stAppViewContainer"]{background:#181420}
[data-testid="stHeader"],footer,[data-testid="stToolbar"],#MainMenu{display:none}
[data-testid="stMainBlockContainer"]{padding:0!important;max-width:none!important}
[data-testid="stVerticalBlock"]{gap:0!important}
iframe[title*="wx_huddle"]{display:block;border:0;width:100%}
</style>''', unsafe_allow_html=True)


@st.cache_resource
def get_service():
    engine = gzip.decompress(base64.b64decode(ENGINE_B64)).decode()
    database = Path(os.environ.get('WX_DATA_DIR', str(Path(tempfile.gettempdir()) / 'wx_huddle_data'))) / 'rooms.sqlite'
    return GameService(engine, database)


@st.cache_resource
def get_component():
    html = gzip.decompress(base64.b64decode(HTML_B64)).decode()
    fingerprint = hashlib.sha256(html.encode()).hexdigest()[:16]
    folder = Path(tempfile.gettempdir()) / ('wx_huddle_frontend_' + fingerprint)
    folder.mkdir(parents=True, exist_ok=True)
    (folder / 'index.html').write_text(html, encoding='utf-8')
    return components.declare_component('wx_huddle_halloween', path=str(folder))


if '_wx_client' not in st.session_state:
    st.session_state['_wx_client'] = secrets.token_hex(24)
    st.session_state['_wx_boot'] = urllib.parse.urlencode({k: st.query_params[k] for k in ('room','display') if k in st.query_params})

service = get_service()
component = get_component()
try:
    public_url = str(st.secrets.get('PUBLIC_APP_URL', ''))
except Exception:
    public_url = ''
if public_url and not re.fullmatch(r'https://[a-zA-Z0-9.-]+(?::[0-9]+)?/?', public_url):
    public_url = ''

message = component(response=st.session_state.get('_wx_response'),
                    boot_query=st.session_state['_wx_boot'], public_url=public_url,
                    key='wx_huddle_game', default=None)
if isinstance(message, dict) and isinstance(message.get('id'), str) and len(message['id']) <= 100:
    if message['id'] != st.session_state.get('_wx_processed'):
        result = service.handle(message, st.session_state['_wx_client'])
        st.session_state['_wx_processed'] = message['id']
        st.session_state['_wx_response'] = {'id': message['id'], **result}
        st.rerun()
